-- content never uses the long dash: "—" / "–" → "-" (the app does the same on every save)
UPDATE "AdwordsAsset" SET "headline" = regexp_replace(regexp_replace("headline", '[ \u00A0]+[—–][ \u00A0]+', ' - ', 'g'), '[—–]', '-', 'g') WHERE "headline" ~ '[—–]';
UPDATE "AdwordsAsset" SET "subheadline" = regexp_replace(regexp_replace("subheadline", '[ \u00A0]+[—–][ \u00A0]+', ' - ', 'g'), '[—–]', '-', 'g') WHERE "subheadline" ~ '[—–]';
